def import_result(lesson_id, known_lessons):
    if lesson_id not in known_lessons:
        return {'ok': False, 'error_code': 'unknown_lesson'}
    return {'ok': True, 'lesson_id': lesson_id}

def test_success_contract():
    result = import_result('loops', {'loops'})
    assert result == {'ok': True, 'lesson_id': 'loops'}

def test_error_contract():
    result = import_result('apis', {'loops'})
    assert result == {'ok': False, 'error_code': 'unknown_lesson'}

test_success_contract()
test_error_contract()
print('success and error contracts checked')

