def result_for(lesson_id):
    if lesson_id == 'loops':
        return {'ok': True, 'lesson_id': 'loops'}
    return {'ok': False, 'error_code': 'unknown_lesson'}

assert result_for('loops') == {'ok': True, 'lesson_id': 'loops'}
assert result_for('apis') == {'ok': False, 'error_code': 'unknown_lesson'}
